class EndpointLoader:
    """Loads endpoint configurations from files"""

    def __init__(self, config_dir: str):
        self.config_dir = Path(config_dir)

    def load_endpoints(self) -> List[Endpoint]:
        """Load all endpoint configurations from YAML files"""
        endpoints = []

        # Find all .yaml and .yml files in the config directory
        for file_path in self.config_dir.rglob("*.yaml"):
            with open(file_path, 'r') as f:
                config = yaml.safe_load(f)

            # Process each endpoint in the file
            for endpoint_config in config.get('endpoints', []):
