import re

@dataclass
class Endpoint:
    """Represents an API endpoint configuration"""
    path: str
    method: str
    handler: str
    schema: Optional[Dict] = None
    middleware: List[str] = None

    def __post_init__(self):
        if self.middleware is None:
            self.middleware = []

@dataclass
class SchemaValidation:
    """Schema validation configuration"""
    name: str
    type: str  # json_schema, openapi, graphql
    file_path: str
    required_fields: List[str] = None

    def __post_init__(self):
        if self.required_fields is None:
            self.required_fields = []

class APISchemaValidator:
    """Validates API schemas against defined rules"""

    def __init__(self):
        self.validators = {
            'json_schema': self._validate_json_schema,
            'openapi': self._validate_openapi,
            'graphql': self._validate_graphql
        }

    def validate(self, schema_config: SchemaValidation) -> Dict[str, Any]:
        """Validate schema based on type"""
        validator = self.validators.get(schema_config.type)
        if not validator:
            return {
                'valid': False,
                'error': f'Unsupported schema type: {schema_config.type}'
            }

        try:
            result = validator(schema_config)
            return {
                'valid': True,
                'details': result
            }
        except Exception as e:
            return {
                'valid': False,
                'error': str(e)
            }

    def _validate_json_schema(self, schema_config: SchemaValidation) -> Dict[str, Any]:
        """Validate JSON schema"""
        with open(schema_config.file_path, 'r') as f:
            schema_data = json.load(f)

        # Basic validation - check if it's valid JSON schema structure
        required_keys = ['type', 'properties']
        missing_keys = [key for key in required_keys if key not in schema_data]

        return {
            'missing_keys': missing_keys,
            'schema_type': 'json'
        }

    def _validate_openapi(self, schema_config: SchemaValidation) -> Dict[str, Any]:
        """Validate OpenAPI schema"""
        with open(schema_config.file_path, 'r') as f:
            schema_data = yaml.safe_load(f)

        # Check basic OpenAPI structure
        required_fields = ['openapi', 'info', 'paths']
        missing_fields = [field for field in required_fields if field not in schema_data]

        return {
            'missing_fields': missing_fields,
            'version': schema_data.get('openapi', 'unknown'),
            'schema_type': 'openapi'
        }

    def _validate_graphql(self, schema_config: SchemaValidation) -> Dict[str, Any]:
        """Validate GraphQL schema"""
