@dataclass
class SchemaDefinition:
    """Represents a single schema definition with metadata"""
    name: str
    version: str
    type: str  # 'contract' or 'event'
    content: Dict[str, Any]
    file_path: str
    dependencies: List[str] = None

    def __post_init__(self):
        if self.dependencies is None:
            self.dependencies = []

@dataclass
class MigrationResult:
    """Result of schema migration operation"""
    success: bool
    message: str
    migrated_schemas: List[Dict[str, Any]] = None
    errors: List[str] = None

    def __post_init__(self):
        if self.migrated_schemas is None:
            self.migrated_schemas = []
        if self.errors is None:
            self.errors = []

class SchemaMigrationEngine:
    """Core engine for handling multi-file schema migrations"""

    def __init__(self, base_dir: str = "."):
        self.base_dir = Path(base_dir)
        self.schemas: Dict[str, SchemaDefinition] = {}
        self.migration_log: List[Dict[str, Any]] = []

    def load_all_schemas(self) -> MigrationResult:
        """Load all schema files from the base directory"""
        result = MigrationResult(success=True, message="Schemas loaded successfully")

        try:
            # Find all schema files (JSON, YAML, YML)
            schema_files = list(self.base_dir.rglob("*schema*.json")) + \
                          list(self.base_dir.rglob("*schema*.yml")) + \
                          list(self.base_dir.rglob("*schema*.yaml"))

            for file_path in schema_files:
                try:
                    schema_data = self._parse_schema_file(file_path)
                    if schema_data:
                        self.schemas[schema_data['name']] = SchemaDefinition(
                            name=schema_data['name'],
                            version=schema_data['version'],
                            type=schema_data['type'],
                            content=schema_data['content'],
                            file_path=str(file_path),
                            dependencies=schema_data.get('dependencies', [])
                        )
                except Exception as e:
                    result.success = False
                    result.errors.append(f"Error loading {file_path}: {str(e)}")

            return result

        except Exception as e:
            return MigrationResult(
                success=False,
                message=f"Failed to load schemas: {str(e)}",
                errors=[str(e)]
