"""
Core multi-file engine for Telemetry Ingestion Pipeline and Metrics Aggregator
"""

import asyncio
import json
import logging
from abc import ABC, abstractmethod
from datetime import datetime
from typing import Dict, List, Any, Optional
from dataclasses import dataclass
from collections import defaultdict

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

@dataclass
class TelemetryEvent:
    """Data class representing a telemetry event"""
    timestamp: datetime
    source: str
    event_type: str
    payload: Dict[str, Any]
    tags: Dict[str, str]

class EventProcessor(ABC):
    """Abstract base class for event processors"""

    @abstractmethod
    def process(self, event: TelemetryEvent) -> List[Dict[str, Any]]:
        """Process a telemetry event and return processed data"""
        pass

class DataIngestor:
    """Handles data ingestion from various sources"""

    def __init__(self):
        self.processors: Dict[str, EventProcessor] = {}
        self.event_queue = asyncio.Queue()

    def register_processor(self, event_type: str, processor: EventProcessor):
        """Register a processor for a specific event type"""
        self.processors[event_type] = processor

    async def ingest_event(self, event: TelemetryEvent):
        """Ingest a telemetry event into the pipeline"""
        logger.info(f"Ingesting event: {event.event_type} from {event.source}")
        await self.event_queue.put(event)

    async def process_events(self):
        """Process events from the queue"""
        while True:
            try:
                event = await self.event_queue.get()
                if event.event_type in self.processors:
                    processed_data = self.processors[event.event_type].process(event)
                    # Here we would typically send to a metrics aggregator
                    logger.info(f"Processed {len(processed_data)} items from {event.event_type}")
                else:
                    logger.warning(f"No processor found for event type: {event.event_type}")
                self.event_queue.task_done()
            except Exception as e:
                logger.error(f"Error processing event: {e}")

class MetricsAggregator:
    """Aggregates metrics from processed telemetry events"""

    def __init__(self):
        self.metrics_storage = defaultdict(list)
        self.aggregation_rules = {}

    def add_aggregation_rule(self, metric_name: str, rule_func):
        """Add an aggregation rule for a specific metric"""
        self.aggregation_rules[metric_name] = rule_func

    def aggregate_metric(self, metric_name: str, value: float, tags: Dict[str, str]):
        """Aggregate a single metric value"""
        self.metrics_storage[metric_name].append({
            'value': value,
            'tags': tags,
            'timestamp': datetime.now()
        })

    def get_aggregated_metrics(self) -> Dict[str, Any]:
        """Get all aggregated metrics with applied rules"""
        result = {}
